const F1_RECENT_LIMIT = 16;
function f1VocabBand(grade){
  return F1_VOCAB_BANDS.find(b=>b.grades.includes(grade)) || F1_VOCAB_BANDS[0];
}
function f1VocabForStudent(grade){
  const selected=grade || (typeof state!=='undefined'&&state.student&&state.student.grade) || 'ป.1';
  return f1VocabBand(selected).words;
}
function f1VocabKey(value){ return String(value||'').trim().toLowerCase(); }
function f1ChooseVocabWord(pool,done,recent,randomFn){
  const source=Array.isArray(pool)?pool:[];
  if(!source.length) return {entry:null,resetDone:false};
  const doneSet=new Set((Array.isArray(done)?done:[]).map(f1VocabKey));
  const recentKeys=(Array.isArray(recent)?recent:[]).slice(-F1_RECENT_LIMIT).map(f1VocabKey);
  const recentSet=new Set(recentKeys);
  let choices=source.filter(([en])=>!doneSet.has(f1VocabKey(en)));
  let resetDone=false;
  if(!choices.length){ choices=source.slice(); resetDone=true; }
  const fresh=choices.filter(([en])=>!recentSet.has(f1VocabKey(en)));
  if(fresh.length) choices=fresh;
  else if(choices.length>1&&recentKeys.length){
    const last=recentKeys[recentKeys.length-1];
    const withoutLast=choices.filter(([en])=>f1VocabKey(en)!==last);
    if(withoutLast.length) choices=withoutLast;
  }
  const rand=typeof randomFn==='function'?randomFn:Math.random;
  const roll=Number(rand());
  const index=Math.min(choices.length-1,Math.max(0,Math.floor((Number.isFinite(roll)?roll:0)*choices.length)));
  return {entry:choices[index],resetDone};
}
